const data = msg.payload || {};

function processAddressPortFields(input) {
    const processed = { ...input };
    const fields = [
        { field: 'gateway_ip_port', addressField: 'gateway_ip', portField: 'gateway_port' },
        { field: 'mqttadresse_port', addressField: 'mqttadresse', portField: 'mqttport' }
    ];

    for (const cfg of fields) {
        const value = processed[cfg.field];
        if (typeof value === 'string' && value.includes(':')) {
            const lastColonIndex = value.lastIndexOf(':');
            processed[cfg.addressField] = value.substring(0, lastColonIndex).trim();
            processed[cfg.portField] = parseInt(value.substring(lastColonIndex + 1), 10);
            delete processed[cfg.field];
        }
    }

    return processed;
}

function asBool(value) {
    if (value === true) return true;
    if (value === false || value === undefined || value === null) return false;

    const s = String(value).trim().toLowerCase();
    return ['true', '1', 'yes', 'y', 'on', 'gateway', 'gateway_ip', 'ip_gateway', 'tcp', 'ethernet', 'network'].includes(s);
}

function detectGatewayMode(cfg) {
    return (
        asBool(cfg.use_gateway) ||
        asBool(cfg.gateway_enabled) ||
        asBool(cfg.enable_gateway) ||
        asBool(cfg.connection_mode) ||
        asBool(cfg.connection_type) ||
        asBool(cfg.transport) ||
        asBool(cfg.interface)
    );
}

function cleanString(value, fallback = '') {
    if (value === undefined || value === null) return fallback;
    const s = String(value).trim();
    return s || fallback;
}

function cleanPort(value, fallback) {
    const n = parseInt(value, 10);
    return Number.isFinite(n) && n > 0 && n <= 65535 ? n : fallback;
}

function defaultStandardFeatures() {
    return {
        mqtt_core: true,
        ha_discovery: true,
        bank_core: true,
        pack_core: true,
        basic_alerts: true,
        influxdb: false,
        grafana: false,
        csv_export: false,
        cycles_soh: false,
        cell_details: false,
        advanced_info: false
    };
}

