function ensureCommandBuffer(command) {
    if (Buffer.isBuffer(command)) {
        const last = command[command.length - 1];
        return last === 13 ? command : Buffer.concat([command, Buffer.from('\r')]);
    }

    const s = String(command || '');
    return Buffer.from(s.endsWith('\r') ? s : s + '\r', 'ascii');
}

// Helper global à appeler depuis les autres function nodes :
