global.set('pylon_gateway_request', function pylonGatewayRequest(command, timeoutMs) {
    const host = String(global.get('gateway_ip') || global.get('gateway_host') || '').trim();
    const port = parseInt(global.get('gateway_port'), 10);
    const timeout = parseInt(timeoutMs || global.get('gateway_timeout') || 5000, 10);

    return new Promise((resolve, reject) => {
        if (!host || !Number.isFinite(port) || port <= 0 || port > 65535) {
            reject(new Error('Gateway IP/port invalide'));
            return;
        }

        const socket = new net.Socket();
        const chunks = [];
        let finished = false;

        function finish(err, data) {
            if (finished) return;
            finished = true;

            socket.removeAllListeners();

            try {
                socket.destroy();
            } catch (e) {
                // ignore
            }

            if (err) reject(err);
            else resolve(data || Buffer.concat(chunks));
        }

        socket.setNoDelay(true);
        socket.setTimeout(timeout);

        socket.on('connect', () => {
            socket.write(ensureCommandBuffer(command));
        });

        socket.on('data', (chunk) => {
            chunks.push(chunk);

            // Les réponses Pylontech RS232 finissent généralement par CR.
            const data = Buffer.concat(chunks);
            if (data.includes(13)) {
                finish(null, data);
            }
        });

        socket.on('timeout', () => {
            finish(new Error(`Timeout gateway ${host}:${port}`));
        });

        socket.on('error', (err) => {
            finish(err);
        });

        socket.on('close', () => {
            if (!finished && chunks.length > 0) {
                finish(null, Buffer.concat(chunks));
            } else if (!finished) {
                finish(new Error(`Gateway ${host}:${port} fermée sans réponse`));
            }
        });

        socket.connect(port, host);
    });
});

