const crypto = global.get('crypto') || require('crypto');

// Cle publique SmartPhoton, identique au module JK-BMS.
const PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEANx4f2OpAbYfWEAGc87l4qX7Hf2nyJCih8nljqLBoMzA=
-----END PUBLIC KEY-----`;

const EXPECTED_PRODUCT = "smartphoton-pylontech";
const EXPECTED_SYSTEM = "pylontech_rs232";
const EXPECTED_TIER = "premium";

function defaultStandardFeatures() {
    return {
        mqtt_core: true,
