}

function b64urlToBuffer(input) {
    let s = String(input || "").trim().replace(/-/g, "+").replace(/_/g, "/");
    while (s.length % 4) s += "=";
    return Buffer.from(s, "base64");
}

function verifySpv2License(license) {
    const parts = String(license || "").trim().split(".");

    if (parts.length !== 3 || parts[0] !== "SPV2") throw new Error("invalid_format");

    const ok = crypto.verify(null, Buffer.from(parts[1], "utf8"), PUBLIC_KEY_PEM, b64urlToBuffer(parts[2]));
    if (!ok) throw new Error("invalid_signature");

    return JSON.parse(b64urlToBuffer(parts[1]).toString("utf8"));
}

function isExpired(expires) {
    const s = String(expires || "").trim();
    if (!s) return false;

    // Licence valide jusqu'a la fin de cette date en UTC.
    const limit = new Date(/^\d{4}-\d{2}-\d{2}$/.test(s) ? s + "T23:59:59.999Z" : s);
    if (Number.isNaN(limit.getTime())) throw new Error("invalid_expiration");

    return Date.now() > limit.getTime();
}

const premiumKey = String(global.get("premium.key") || "").trim();

const installId =
    String(global.get("premium.install_id") || "").trim() ||
    String(flow.get("premium_install_id", "persistent") || "").trim();

let active = false;
let status = "missing";
let tier = "standard";
let features = defaultStandardFeatures();

const lic = {
    valid: false,
    tier: "standard",
    product: "smartphoton-pylontech",
    license_id: null,
    customer: null,
    issued_at: null,
    bound_to: installId || null,
    error: "missing_or_invalid_license",
    features
};

if (!premiumKey) {
    status = "missing";
} else {
    try {
        if (!installId) throw new Error("missing_install_id");

        const payload = verifySpv2License(premiumKey);

        if (Number(payload.v) !== 2) throw new Error("invalid_payload_version");
        if (payload.iss !== "SmartPhoton") throw new Error("invalid_issuer");
        if (payload.product !== EXPECTED_PRODUCT) throw new Error("invalid_product");
        if (payload.system !== EXPECTED_SYSTEM) throw new Error("invalid_system");
        if (payload.tier !== EXPECTED_TIER) throw new Error("invalid_tier");
        if (String(payload.install_id || "").trim() !== installId) throw new Error("install_id_mismatch");
        if (isExpired(payload.expires_at)) throw new Error("expired");

        active = true;
        status = "valid";
        tier = payload.tier;
        features = { ...defaultPremiumFeatures(), ...(payload.features || {}) };

        lic.license_id = payload.license_id || null;
        lic.customer = payload.customer || null;
        lic.issued_at = payload.issued_at || null;
        lic.valid = true;
        lic.tier = tier;
        lic.error = null;
        lic.features = features;
    } catch (e) {
        status = e.message || "invalid_license";
        active = false;
        tier = "standard";
        features = defaultStandardFeatures();

        lic.error = status;
        lic.features = features;
    }
}

