function gatewayModeActive() {
    const mode = String(global.get('pylon_transport') || global.get('pylon_connection_mode') || '').trim().toLowerCase();
    return mode === 'gateway' || mode === 'tcp' || mode === 'ip_gateway' || global.get('use_gateway') === true || global.get('gateway_enabled') === true;
}

if (gatewayModeActive()) {
    node.status({ fill: 'blue', shape: 'ring', text: 'gateway actif : polling USB ignoré' });
    return null;
}

function chooseOrFallbackBranch() {
    let branch = flow.get('pylon_model_branch') || global.get('pylon_model_branch') || null;
    let family = flow.get('pylon_model_family') || global.get('pylon_model_family') || null;
    if (branch) return { ok: true, branch, family: family || (branch === 'modern_pack' ? 'MODERN' : 'US2000B'), fallback: false };

    const now = Date.now();
    const started = Number(flow.get('pylon_model_detect_started_at') || flow.get('pylon_usb_model_detect_started_at') || 0);

    // On laisse le temps à info 1 de revenir avant de décider.
    if (started && (now - started) < 20000) {
        return { ok: false, wait: true, age_ms: now - started };
    }

    // Fallback conservateur pour ne pas casser les installations US2000B existantes.
    branch = 'us2000b_global';
    family = 'US2000B';

    flow.set('pylon_model_family', family);
    flow.set('pylon_model_branch', branch);
    flow.set('pylon_model_command_mode', 'pwr_global');
    flow.set('pylon_model_parser', 'pwr_global_table');
    flow.set('pylon_model_detected', false);
    flow.set('pylon_model_detecting', false);
    flow.set('pylon_model_detect_confidence', 'fallback_no_info1_usb');

    global.set('pylon_model_family', family);
    global.set('pylon_model_branch', branch);
    global.set('pylon_model_command_mode', 'pwr_global');
    global.set('pylon_model_parser', 'pwr_global_table');
    global.set('pylon_model_detected', false);
    global.set('pylon_model_detecting', false);

    let meta = flow.get('pylon_meta') || {};
    meta.model_family = family;
    meta.model_branch = branch;
    meta.model_command_mode = 'pwr_global';
    meta.model_parser = 'pwr_global_table';
    meta.model_detect_confidence = 'fallback_no_info1_usb';
    meta.cells = Number(meta.cells) || 15;
    if (!meta.packs) meta.packs = Number(global.get('pylon_default_packs') || 5) || 5;
    flow.set('pylon_meta', meta);
    global.set('pylon_meta', meta);

    return { ok: true, branch, family, fallback: true };
}

const BASE = flow.get('pylon_base') || global.get('mqtt_base_topic') || 'pylontech1';
let meta = flow.get('pylon_meta') || {};
const packs = Number(meta.packs) || 0;
if (packs <= 0) return null;

const selected = chooseOrFallbackBranch();
if (!selected.ok) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'USB : attente détection modèle...' });
    return null;
}

const tasks = [];

if (selected.branch === 'us2000b_global') {
    // US2000B : une seule commande globale pwr, réponse tableau multi-batteries.
    tasks.push({ kind:'pwr_global', index:0, cmd:'pwr' });
    node.status({ fill: selected.fallback ? 'yellow' : 'green', shape: 'dot', text: 'USB ' + selected.family + ' : pwr global' });
} else {
    // US2000C / US3000 / US5000 / récents : commande par adresse.
    for (let i=1;i<=packs;i++) tasks.push({ kind:'pwr', index:i, cmd:`pwr ${i}` });
    node.status({ fill: 'blue', shape: 'dot', text: 'USB ' + selected.family + ' : pwr 1..' + packs });
}

msg.payload = tasks;
return msg;

