const BASE = flow.get('pylon_base') || global.get('mqtt_base_topic') || 'pylontech1';
const MAX_ADDR = 15;
const tasks = [];
for (let i=1;i<=MAX_ADDR;i++) tasks.push({ kind:'stat', index:i, cmd:`stat ${i}` });
msg.payload = tasks;
return msg;

function gatewayModeActive() {
    const mode = String(global.get('pylon_transport') || global.get('pylon_connection_mode') || '').trim().toLowerCase();
    return mode === 'gateway' || mode === 'tcp' || mode === 'ip_gateway' || global.get('use_gateway') === true || global.get('gateway_enabled') === true;
