  if (Number.isFinite(p.soc)) socs.push(p.soc);
  if (Number.isFinite(p.power)) totalPower += p.power;
  if (Number.isFinite(p.current)) totalCurrent += p.current;

  if (Number.isFinite(p.voltage)) {
    totalVoltage += p.voltage;
    voltageCount++;
  }
}

let bank = {};

bank.packs_present = packsMax;
bank.packs_online = online;

// noms d'origine
bank.power_total = Math.round(totalPower);
bank.current_total = Math.round(totalCurrent * 100) / 100;

if (voltageCount > 0) {
  bank.voltage_avg = Math.round((totalVoltage / voltageCount) * 100) / 100;
}

if (socs.length > 0) {
  const avg = socs.reduce((a, b) => a + b, 0) / socs.length;
  bank.soc_avg = Math.round(avg * 10) / 10;
  bank.soc_min = Math.min(...socs);
  bank.soc_max = Math.max(...socs);
}

// alias compatibles dashboard / discovery
bank.total_power = bank.power_total;
bank.total_current = bank.current_total;
