function pickNum(re) {
  const m = buf.match(re);
  if (!m) return null;
  const n = Number(String(m[1]).replace(/[^\d\-.]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function pickStr(re) { const m = buf.match(re); return m ? String(m[1]).trim() : null; }
function setIf(obj, key, val) { if (val !== null && val !== undefined && val !== '') obj[key] = val; }

const cycles = pickNum(/CYCLE\s*Times\s*:\s*(\d+)/i) ?? pickNum(/Cycle\s*Times\s*:\s*(\d+)/i) ?? pickNum(/\bCycles?\s*:\s*(\d+)/i);
const soh = pickNum(/(?:^|\n)\s*SOH\s*:\s*(\d+)\s*%?/i) ?? pickNum(/Soh\.?\s*:\s*(\d+)\s*%?/i);

const statInfo = { last_stat_seen: now, last_stat_seen_iso: new Date(now).toISOString(), stat_raw_available: true };
setIf(statInfo, 'cycles', cycles);
setIf(statInfo, 'soh', soh);
setIf(statInfo, 'base_status', pickStr(/Basic\s+Status\s*:\s*([^\r\n]+)/i) || pickStr(/Base\.?St\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'volt_status', pickStr(/Volt\s+Status\s*:\s*([^\r\n]+)/i) || pickStr(/Voltage\s+Status\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'current_status', pickStr(/Current\s+Status\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'tmpr_status', pickStr(/Tmpr\.?\s+Status\s*:\s*([^\r\n]+)/i) || pickStr(/Temp\.?\s+Status\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'coul_status', pickStr(/Coul\.?\s+Status\s*:\s*([^\r\n]+)/i) || pickStr(/Coulomb\s+Status\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'soh_status', pickStr(/Soh\.?\s+Status\s*:\s*([^\r\n]+)/i) || pickStr(/SOH\s+Status\s*:\s*([^\r\n]+)/i));
setIf(statInfo, 'heater_status', pickStr(/Heater\s+Status\s*:\s*([^\r\n]+)/i));

if (Object.keys(statInfo).length <= 3) {
  flow.set(key, buf);
  return null;
}

let packs = flow.get('pylon_packs') || {};
let p = packs[nn] || { battery_id: index };
p = Object.assign({}, p, statInfo);
p.stat = Object.assign({}, p.stat || {}, statInfo);
p.last_seen = p.last_seen || now;
p.source = p.source || 'serial_usb';
