// Lecture Gateway TCP depuis la page config add-on.
// Branches auto :
// - us2000b_global : commande globale "pwr" + parser tableau US2000B
// - modern_pack    : commandes "pwr 1..N" + parser individuel modèles récents
function gatewayModeActive() {
    const mode = String(global.get('pylon_transport') || global.get('pylon_connection_mode') || '').trim().toLowerCase();
    return mode === 'gateway' || mode === 'tcp' || mode === 'ip_gateway' || global.get('use_gateway') === true || global.get('gateway_enabled') === true;
}

function gatewayEndpoint() {
    const host = String(global.get('gateway_ip') || global.get('gateway_host') || global.get('pylon_gateway_host') || '').trim();
    const port = parseInt(global.get('gateway_port') || global.get('pylon_gateway_port') || 0, 10);

    if (!host || !Number.isFinite(port) || port <= 0 || port > 65535) {
        return { ok: false, error: 'gateway_ip/gateway_port invalide', host, port };
    }

    return { ok: true, host, port };
}

function modelHintFromKnownInfo() {
    const meta = flow.get('pylon_meta') || {};
    const packs = flow.get('pylon_packs') || {};
    const parts = [];
    function add(v) { if (v !== null && v !== undefined && v !== '') parts.push(String(v)); }
    ['model_name','device_name','specification','model_family','model_branch'].forEach(k => add(meta[k]));
    Object.keys(packs || {}).forEach(k => {
        const p = packs[k] || {};
        const info = p.info || p.info_full || {};
        ['device_name','specification','manufacturer','board_version','main_soft','soft_version','barcode'].forEach(x => { add(p[x]); add(info[x]); });
    });
    const text = parts.join('\n').toUpperCase();
    if (/\bUS\s*2000\s*C\b|\bUS2000C\b|\b2000C\b|\bUS3000\b|\bUS5000\b|\bUP5000\b|\bPELIO\b|\bFORCE\b|\bH48050\b|\bFH9637\b|\bE-BOX\b/.test(text)) {
        return { family:'MODERN', branch:'modern_pack', command_mode:'pwr_n', parser:'pwr_pack_individual', confidence:'known_info_modern' };
    }
    if (/\bUS\s*2000\s*B\b|\bUS2000B\b|\b2000B\b/.test(text)) {
        return { family:'US2000B', branch:'us2000b_global', command_mode:'pwr_global', parser:'pwr_global_table', confidence:'known_info_us2000b' };
    }
    return null;
}
function applyModelDecision(decision, detected) {
    const branch = decision.branch;
    const family = decision.family;
    flow.set('pylon_model_branch', branch);
    flow.set('pylon_model_family', family);
    flow.set('pylon_model_command_mode', decision.command_mode);
    flow.set('pylon_model_parser', decision.parser);
    flow.set('pylon_model_detected', !!detected);
    flow.set('pylon_model_detecting', false);
    flow.set('pylon_model_detect_confidence', decision.confidence);
    global.set('pylon_model_branch', branch);
    global.set('pylon_model_family', family);
    global.set('pylon_model_command_mode', decision.command_mode);
    global.set('pylon_model_parser', decision.parser);
    global.set('pylon_model_detected', !!detected);
    global.set('pylon_model_detecting', false);
    let meta = flow.get('pylon_meta') || {};
    meta.model_family = family;
    meta.model_branch = branch;
    meta.model_command_mode = decision.command_mode;
    meta.model_parser = decision.parser;
    meta.model_detect_confidence = decision.confidence;
    meta.cells = Number(meta.cells) || 15;
    if (!meta.packs) meta.packs = Number(global.get('pylon_default_packs') || 5) || 5;
    flow.set('pylon_meta', meta);
    global.set('pylon_meta', meta);
    return { ok: true, branch, family, fallback: !detected, confidence: decision.confidence };
}
function ensureBranchReady() {
    let branch = flow.get('pylon_model_branch') || global.get('pylon_model_branch') || null;
    let family = flow.get('pylon_model_family') || global.get('pylon_model_family') || null;

    // Correction importante : si un info déjà lu indique US2000C/US3000/US5000,
    // on écrase un ancien fallback US2000B resté en mémoire flow/global.
    const hint = modelHintFromKnownInfo();
    if (hint && (!branch || branch !== hint.branch || family !== hint.family)) {
        return applyModelDecision(Object.assign({}, hint, { confidence: 'corrected_from_info_' + hint.confidence }), true);
    }

    if (branch) return { ok: true, branch, family: family || (branch === 'modern_pack' ? 'MODERN' : 'US2000B'), fallback: false };

    const started = Number(flow.get('pylon_gateway_model_detect_started_at') || 0);
    const now = Date.now();

    // Si le detect info 1 vient de partir, on attend la réponse au lieu de partir au hasard.
    if (started && (now - started) < 15000) {
        return { ok: false, wait: true, age_ms: now - started };
    }

    // Fallback prudent : US2000B pour ne pas casser les installations existantes.
    return applyModelDecision({ family:'US2000B', branch:'us2000b_global', command_mode:'pwr_global', parser:'pwr_global_table', confidence:'fallback_no_info1' }, false);
}

