}
const knownModel = inferModelFromKnownInfo();
const family = msg._pylon_model_family || (knownModel && knownModel.family) || flow.get('pylon_model_family') || global.get('pylon_model_family') || 'US2000B';
const branch = msg._pylon_model_branch || (knownModel && knownModel.branch) || flow.get('pylon_model_branch') || global.get('pylon_model_branch') || (family === 'MODERN' || family === 'US2000C' ? 'modern_pack' : 'us2000b_global');
const gwHost = String(msg._gateway_host || msg.host || global.get('gateway_ip') || global.get('gateway_host') || '').trim();
