const source = String(msg._source || (transport === 'gateway' ? 'elfin_tcp' : 'serial_usb'));

flow.set('pylon_last_raw_pwr', raw);
flow.set(transport === 'gateway' ? 'pylon_elfin_last_raw_pwr' : 'pylon_usb_last_raw_pwr', raw);
flow.set(transport === 'gateway' ? 'pylon_elfin_last_rx_at' : 'pylon_usb_last_rx_at', now);
