        global.set('pylon_model_name', meta.model_name);
        global.set('pylon_model_detected', true);
        global.set('pylon_model_detecting', false);
    }
}
flow.set('pylon_meta', meta);
global.set('pylon_meta', meta);

const out = [];
out.push(mqtt(BASE + '/battery/' + nn + '/info', info, true));
out.push(mqtt(BASE + '/battery/' + nn + '/state', p, true));
out.push(mqtt(BASE + '/debug/elfin/info/' + nn, raw, false));
if (index === 1) {
    out.push(mqtt(BASE + '/system/model', Object.assign({ packs: meta.packs || null, cells: meta.cells || info.cell_number || 15, detected_at: now }, meta, { model_name: meta.model_name || info.device_name || global.get('pylon_model_name') || 'Pylontech' }), true));
}
node.status({fill:'green',shape:'dot',text:'info ' + index + ': ' + (info.device_name || info.specification || 'OK')});
return [out];

const premiumActive = global.get("premium.active") === true;
if (!premiumActive) return null;

const fs = global.get("fs");
const dir = "/config/www/smart-modular-dashboard";
const lang = String(global.get("config.dashboardLanguage") || "fr").toLowerCase() === "en" ? "en" : "fr";

try {
    fs.mkdirSync(dir, { recursive: true });
    fs.copyFileSync("/etc/node-red/pylontech.html", dir + "/pylontech.html");
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: "deploiement HTML impossible" });
    node.error("Deploiement du dashboard HTML impossible: " + e.message, msg);
    return null;
}

const title = "Smart Pylontech HTML";
const url = "/local/smart-modular-dashboard/pylontech.html?lang=" + lang + "&v=" + Date.now();
msg.filename = "/config/dashboards/smart_pylontech_html.json";
msg.payload = JSON.stringify({
    dashboard_meta: { url_path: "smart-pylontech-html", title, icon: "mdi:battery-high", show_in_sidebar: true, require_admin: false },
    config: { views: [{ title, path: "home", icon: "mdi:battery-high", panel: true, cards: [{ type: "iframe", url, aspect_ratio: "100%" }] }] }
}, null, 2);
node.status({ fill: "green", shape: "dot", text: "dashboard HTML pret / lang=" + lang });
return msg;
